"use strict";
(function(){
let variant=1,active='input',answers={},scores={},counts={};
const labels={input:'Так або ні',output:'Правильно чи неправильно',decode:'Розкодуй',tasks:'Задачі'};
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const getData=()=>active==='tasks'?window.PYTHON_TASKS[variant-1]:window.NEW_PRACTICE_DATA[variant-1][active];
const getKey=()=>variant+'-'+active;
const norm=s=>String(s).replace(/\r/g,'').trim().replace(/\u00a0/g,' ');
function render(){
const root=document.getElementById('new-practice-root');if(!root)return;
root.innerHTML=`<a class="back" href="#examples">← До прикладів</a><section class="comic np-hero"><img class="np-cover" src="assets/exercises.webp" alt="Комікс Вправи"><div><span class="pill">🎮 Інтерактивний практикум Python</span><h1>ВПРАВИ!</h1><p>Введення та виведення даних: перевір код, знайди помилки й розкодуй результат.</p><label class="np-label" for="np-variant">Обери варіант</label><select id="np-variant">${[1,2,3,4,5].map(i=>`<option value="${i}" ${variant===i?'selected':''}>Варіант ${i}</option>`).join('')}</select></div></section><div class="np-tabs">${Object.entries(labels).map(([k,t])=>`<button type="button" class="${active===k?'active':''}" data-np="${k}">${k==='input'?'👍':k==='output'?'🔍':k==='decode'?'🔐':'🧩'} ${t}</button>`).join('')}</div>${active==='tasks'?`<section class="comic np-work"><h2>Задачі · варіант ${variant}</h2><p>Введення даних, арифметичні операції, робота з цифрами числа та логічне мислення.</p>${getData().map((item,i)=>`<article class="np-question" style="display:block"><div class="np-task-title">${safe((item.match(/^Задача \d+\.\s*[^.]+\./)||[])[0]||`Задача ${i+1}`)}</div><p class="np-task-text">${safe(item.replace(/^Задача \d+\.\s*[^.]+\.\s*/,'')).replace(/\n/g,'<br>')}</p></article>`).join('')}</section>`:`<section class="comic np-work ${active==='decode'?'np-decode':'np-binary'}"><h2>${labels[active]}</h2><p>${active==='input'?'Визнач, чи правильно записано код введення даних.':active==='output'?'Знайди синтаксично правильні та неправильні записи виведення даних.':'Уважно прочитай код і введи точний результат, який з’явиться на екрані.'} Кожна правильна відповідь — 1 бал.</p><div id="np-items">${getData().map((item,i)=>`<div class="np-question"><div class="np-number">${i+1}</div><pre><code>${safe(item.code)}</code></pre><div class="np-answer">${active==='decode'?`<label for="np-a-${i}">Результат:</label><textarea id="np-a-${i}" data-index="${i}" rows="2" spellcheck="false" placeholder="Запиши результат точно">${safe((answers[getKey()]||{})[i]||'')}</textarea>`:`<div class="choice-row np-choices"><button type="button" data-index="${i}" data-value="true" class="${(answers[getKey()]||{})[i]==='true'?'chosen good':''}">${active==='input'?'👍 Так':'✅ Правильно'}</button><button type="button" data-index="${i}" data-value="false" class="${(answers[getKey()]||{})[i]==='false'?'chosen bad':''}">${active==='input'?'Ні 👎':'❌ Неправильно'}</button></div>`}</div><div class="np-feedback" id="np-f-${i}"></div></div>`).join('')}</div><button class="action-check np-check" id="np-check">✅ Перевірити відповіді</button><div id="np-summary" role="status" aria-live="polite"></div></section><section class="comic np-work np-overview"><h2>🏆 Результати варіанта ${variant}</h2><div>${Object.entries(labels).map(([k,t])=>`<p>${t}: <strong>${scores[variant+'-'+k]===undefined?'ще не виконано':scores[variant+'-'+k]+'/12'}</strong> · Спроб: ${counts[variant+'-'+k]||0}</p>`).join('')}</div><p class="np-note">Це окремий практикум. Результати перевірки відображаються тут; автоматичне надсилання до Gmail для нього поки не підключено.</p></section>`}`;
document.getElementById('np-variant').onchange=e=>{variant=Number(e.target.value);active='input';render()};
document.querySelectorAll('[data-np]').forEach(b=>b.onclick=()=>{active=b.dataset.np;render()});
document.querySelectorAll('#np-items textarea').forEach(el=>el.addEventListener('input',e=>{(answers[getKey()] ||= {})[Number(e.target.dataset.index)]=e.target.value}));
document.querySelectorAll('.np-choices button').forEach(el=>el.addEventListener('click',()=>{(answers[getKey()] ||= {})[Number(el.dataset.index)]=el.dataset.value;el.parentElement.querySelectorAll('button').forEach(b=>{b.className=b===el?'chosen '+(el.dataset.value==='true'?'good':'bad'):''});}));
if(active!=='tasks')document.getElementById('np-check').onclick=check;
}
function check(){
const key=getKey(),items=getData();let score=0;const a=answers[key]||{};
items.forEach((item,i)=>{const value=a[i],expected=active==='decode'?norm(item.answer):String(item.correct);const correct=active==='decode'?norm(value||'')===expected:value===expected;if(correct)score++;const el=document.getElementById('np-f-'+i);el.className='np-feedback '+(correct?'np-good':'np-bad');el.textContent=correct?'✓ Правильно':`✗ ${active==='decode'?'Правильний результат: '+item.answer:'Правильна відповідь: '+(item.correct?(active==='input'?'Так':'Правильно'):(active==='input'?'Ні':'Неправильно'))}`;});
scores[key]=score;counts[key]=(counts[key]||0)+1;
document.getElementById('np-summary').innerHTML=`<h3>Результат: ${score} / 12 балів</h3><p>Кількість спроб: ${counts[key]}. Можна виправити відповіді та перевірити ще раз.</p>`;
const overview=document.querySelector('.np-overview');overview.querySelector('div').innerHTML=Object.entries(labels).map(([k,t])=>`<p>${t}: <strong>${scores[variant+'-'+k]===undefined?'ще не виконано':scores[variant+'-'+k]+'/12'}</strong> · Спроб: ${counts[variant+'-'+k]||0}</p>`).join('');
}
window.renderNewPractice=render;
})();
;
