window.CONDITIONAL_PROBLEMS=[{"heading": "Варіант 1. Цифровий світ", "items": [{"name": "Задача 1. Заряд смартфона.", "text": "Введи рівень заряду батареї у відсотках. Якщо він менший за 20, виведи «Потрібна зарядка», інакше — «Заряду достатньо»."}, {"name": "Задача 2. Пакування файлів.", "text": "Введи кількість фотографій. Визнач, чи можна розділити їх порівну між 4 папками без залишку."}, {"name": "Задача 3. Баланс рахунку.", "text": "Введи баланс електронного гаманця. Визнач, чи є на рахунку кошти, заборгованість або нульовий баланс."}, {"name": "Задача 4. Швидкість інтернету.", "text": "Введи швидкість інтернету в Мбіт/с (від 0 до 100). Визнач якість: менше 10 — «Повільний», від 10 до 29 — «Середній», від 30 до 69 — «Швидкий», від 70 — «Дуже швидкий»."}, {"name": "Задача 5. Доступ до онлайн-гри.", "text": "Введи вік користувача та кількість набраних балів. Доступ до турніру надається, якщо вік не менший за 14 років і балів не менше 100."}, {"name": "Задача 6. Резервне копіювання.", "text": "Хмарне сховище працює за циклом із 5 днів. У другий і п’ятий дні кожного циклу система автоматично створює резервну копію файлів. В інші дні резервне копіювання не виконується. Дано номер дня k (1 ≤ k ≤ 365). Визнач, чи створюється резервна копія цього дня."}]}, {"heading": "Варіант 2. Подорожі та транспорт", "items": [{"name": "Задача 1. Вага валізи.", "text": "Введи вагу багажу. Якщо вона перевищує 20 кг, виведи «Потрібна доплата», інакше — «Багаж дозволено»."}, {"name": "Задача 2. Розміщення пасажирів.", "text": "Введи кількість туристів. Визнач, чи можна розмістити всіх у тримісних номерах без вільних місць."}, {"name": "Задача 3. Рух ліфта.", "text": "Введи номер поверху, на якому перебуває ліфт, відносно нульового рівня. Визнач, чи ліфт вище нульового рівня, нижче нього або на нульовому рівні."}, {"name": "Задача 4. Знижка на квиток.", "text": "Введи вік пасажира (від 0 до 100 років). Визнач категорію: до 6 років — «Безкоштовно», від 6 до 13 — «Дитячий», від 14 до 59 — «Повний», від 60 — «Пільговий»."}, {"name": "Задача 5. Оренда електросамоката.", "text": "Введи вік користувача та заряд самоката. Оренда дозволена, якщо користувачу не менше 16 років і заряд не нижчий за 30%."}, {"name": "Задача 6. Екскурсійний автобус.", "text": "Туристичний автобус працює за циклом із 6 днів. У перший і четвертий дні кожного циклу він здійснює екскурсію до замку. В інші дні автобус їздить за звичайним маршрутом. Дано номер дня k (1 ≤ k ≤ 360). Визнач, чи вирушає автобус на екскурсію до замку цього дня."}]}, {"heading": "Варіант 3. Школа та навчання", "items": [{"name": "Задача 1. Виконання тесту.", "text": "Введи кількість правильних відповідей із 20 запитань. Якщо їх не менше 12, виведи «Тест складено», інакше — «Повтори матеріал»."}, {"name": "Задача 2. Робота в командах.", "text": "Введи кількість учнів. Визнач, чи можна розділити їх на команди по 5 осіб без залишку."}, {"name": "Задача 3. Зміна рейтингу.", "text": "Введи зміну рейтингу учня за тиждень. Визнач, чи рейтинг зріс, знизився або залишився незмінним."}, {"name": "Задача 4. Рівень володіння Python.", "text": "Введи кількість виконаних завдань (від 0 до 20). Визнач рівень: 0–4 — «Новачок», 5–9 — «Учень», 10–15 — «Програміст», 16–20 — «Експерт»."}, {"name": "Задача 5. Участь в олімпіаді.", "text": "Введи клас учня та результат відбіркового тесту. Учень допускається до олімпіади, якщо навчається не нижче 8 класу та набрав щонайменше 70 балів."}, {"name": "Задача 6. Робот у STEM-лабораторії.", "text": "Навчальний робот працює за циклом із 4 команд. Перші дві команди кожного циклу — рух уперед, третя — поворот, четверта — зупинка. Після четвертої команди цикл повторюється. Дано номер команди k (1 ≤ k ≤ 400). Визнач, чи рухається робот уперед під час виконання цієї команди."}]}, {"heading": "Варіант 4. Покупки та фінанси", "items": [{"name": "Задача 1. Безкоштовна доставка.", "text": "Введи суму замовлення. Якщо вона не менша за 800 грн, виведи «Доставка безкоштовна», інакше — «Доставка платна»."}, {"name": "Задача 2. Пакування цукерок.", "text": "Введи кількість цукерок. Визнач, чи можна розкласти їх у коробки по 6 штук без залишку."}, {"name": "Задача 3. Прибуток магазину.", "text": "Введи різницю між доходами та витратами магазину. Визнач, чи магазин отримав прибуток, збиток або вийшов на нуль."}, {"name": "Задача 4. Програма лояльності.", "text": "Введи суму покупок за місяць (від 0 до 20 000 грн). Визнач статус клієнта: менше 1000 — «Звичайний», 1000–2999 — «Бронзовий», 3000–6999 — «Срібний», від 7000 — «Золотий»."}, {"name": "Задача 5. Покупка ноутбука.", "text": "Введи кількість грошей покупця та вартість ноутбука. Покупка можлива, якщо грошей вистачає і ціна ноутбука не перевищує встановлений бюджет 30 000 грн."}, {"name": "Задача 6. Дні знижок.", "text": "Інтернет-магазин проводить акції за циклом із 7 днів. У третій і шостий дні кожного циклу діє спеціальна знижка 20%. В інші дні товари продаються за звичайною ціною. Дано номер дня k (1 ≤ k ≤ 365). Визнач, чи діє спеціальна знижка цього дня."}]}, {"heading": "Варіант 5. Спорт та здоровий спосіб життя", "items": [{"name": "Задача 1. Тренування бігуна.", "text": "Введи кількість подоланих кілометрів. Якщо спортсмен пробіг не менше 5 км, виведи «Мету досягнуто», інакше — «Продовжуй тренування»."}, {"name": "Задача 2. Формування команд.", "text": "Введи кількість гравців. Визнач, чи можна сформувати команди по 7 гравців без залишку."}, {"name": "Задача 3. Зміна ваги спортсмена.", "text": "Введи зміну ваги за місяць у кілограмах. Визнач, чи вага збільшилася, зменшилася або не змінилася."}, {"name": "Задача 4. Рівень фізичної активності.", "text": "Введи кількість хвилин тренування за день (від 0 до 300). Визнач рівень: менше 15 — «Низький», 15–29 — «Помірний», 30–59 — «Активний», від 60 — «Високий»."}, {"name": "Задача 5. Участь у марафоні.", "text": "Введи вік спортсмена та кількість кілометрів, які він пробіг на останньому тренуванні. До марафону допускаються учасники від 18 років, які пробігли не менше 10 км."}, {"name": "Задача 6. Графік тренувань.", "text": "Спортсмен тренується за циклом із 5 днів. У перший і четвертий дні кожного циклу він виконує силові вправи. В інші дні займається іншими видами фізичної активності. Дано номер дня k (1 ≤ k ≤ 365). Визнач, чи заплановане силове тренування цього дня."}]}];

