'use strict';
/* Standalone exercises: restricted, deterministic evaluator for educational Python subset. */
function renderConditionalExtras(host,kind,variant){
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const names={assemble:'🧩 Збери програму',doors:'🚪 Три двері — три умови',lock:'🔐 Зламай кодовий замок',fix:'🛠️ Виправ програміста',challenge:'⚡ Python-челендж: допиши код',problems:'📚 Задачі'};
 const count={assemble:6,doors:12,lock:12,fix:5,challenge:12,problems:5}[kind];
 const tasks=Array.from({length:count},(_,i)=>{let a=3+variant*3+(i%5)*2,b=a+4+(i%3),x=[a-2,a,a+2,b,b+3][(i+variant)%5];return {a,b,x,i,expected:x<a?1:x<b?2:3};});
 const score=new Set(),wrong={},attempts={},state={};let active=0;
 const labels=['Мала кількість','Середня кількість','Велика кількість'];
 function source(t,broken=false){return `x = ${t.x}\nif x < ${t.a}:\n    result = 1\nelif x ${broken?'>':'<'} ${t.b}:\n    result = 2\nelse:\n    result = 3\nprint(f"{result}")`}
 function evaluate(src,value){ // Evaluates only explicit x comparisons and integer result assignments; never evals user code.
  const ls=src.replace(/\r/g,'').split('\n');let seen=false,chosen=false,out=null,branches=0;
  for(const raw of ls){if(!raw.trim())continue;const t=raw.trim();let m;
   if((m=/^(if|elif) x (<=|>=|==|!=|<|>) (-?\d+):$/.exec(t))){if(raw!==t)return {error:'Умови повинні починатися без відступу.'};if(m[1]==='if'&&branches!==0||m[1]==='elif'&&branches===0)return {error:'Неправильний порядок гілок.'};branches++;let n=+m[3],op=m[2],ok=op==='<'?value<n:op==='>'?value>n:op==='<='?value<=n:op==='>='?value>=n:op==='=='?value===n:value!==n;chosen=!seen&&ok;if(chosen)seen=true;continue}
   if(t==='else:'){if(raw!==t||!branches)return {error:'Перевір розташування else.'};branches++;chosen=!seen;seen=true;continue}
   if((m=/^result = (-?\d+)$/.exec(t))){if(!raw.startsWith('    ')||raw.startsWith('     ')||!branches)return {error:'Потрібні рівно 4 пробіли перед командою гілки.'};if(chosen)out=+m[1];continue}
   if(/^x = -?\d+$/.test(t)||t==='print(f"{result}")')continue;
   return {error:'Непідтримуваний або неправильний рядок: '+t};
  }return {value:out,error:out===null?'Не отримано результат.':''};
 }
 const stats=()=>{let a=Object.values(attempts).reduce((s,v)=>s+v,0),w=Object.values(wrong).reduce((s,v)=>s+v,0);return `Правильних завдань: ${score.size}/${count} · Неправильних відповідей: ${w} · Усього спроб: ${a}`};
 host.innerHTML=`<section class="comic np-work cp-extra"><h2>${names[kind]}</h2><p>${kind==='assemble'?'Прочитай умову задачі та склади програму з перемішаних рядків. Відступи вже вказані на картках.':kind==='doors'?'Прочитай програму та обери двері першої виконаної гілки.':kind==='lock'?'Обчисли результат виконання програми. Для кожного сейфа є три спроби.':kind==='fix'?'Зліва — умова задачі, у центрі — код із логічною помилкою, справа — тести. Виправ лише логіку.':kind==='challenge'?'Зліва — завдання, у центрі — редактор, справа — тестові значення. Замінюй пропуски __.':'Розв’яжи шість задач, використовуючи умовні оператори Python.'}</p><div class="cp-extra-progress" id="ce-stats"></div><div id="ce-stage"></div><div class="cp-extra-footer"><button class="ce-action" id="ce-reset">↻ Почати заново</button></div></section>`;
 const stage=host.querySelector('#ce-stage');
 function record(i,ok){attempts[i]=(attempts[i]||0)+1;if(ok)score.add(i);else wrong[i]=(wrong[i]||0)+1;host.querySelector('#ce-stats').textContent=stats()}
 function message(box,ok,txt){box.className='ce-message '+(ok?'ce-pass':'ce-fail');box.textContent=txt}
 function checkButton(container,fn,label='✓ Перевірити'){let b=document.createElement('button');b.className='ce-action';b.textContent=label;b.onclick=fn;container.append(b);return b}
 const grid=(cards,cls='ce-task-grid')=>{let wrap=document.createElement('div');wrap.className=cls;cards.forEach(c=>wrap.append(c));stage.append(wrap)};
 function card(i){let el=document.createElement('article');el.className='ce-task-card';el.innerHTML=`<h3>Завдання ${i+1} </h3>`;return el}
 function code(text){let pre=document.createElement('pre');pre.className='ce-code';let c=document.createElement('code');c.textContent=text;pre.append(c);return pre}
 function info(el,txt){let p=document.createElement('p');p.className='ce-instruction';p.textContent=txt;el.append(p)}
 if(kind==='assemble'){
  const situations=['Визнач, чи число менше першої межі, між межами або більше другої.','Класифікуй кількість балів: низька, середня або висока.','Визнач рівень заряду батареї за двома порогами.','Визнач рівень температури за двома межами.','Визнач розмір покупки за двома межами.','Визнач категорію швидкості за двома межами.'];
  let cards=tasks.map((t,i)=>{let el=card(i),lines=source(t).split('\n');let initial=[3,0,6,2,7,1,5,4].filter(n=>n<lines.length);let order=state[i]||initial.slice();state[i]=order;info(el,`${situations[i]} Значення x = ${t.x}, межі ${t.a} та ${t.b}. Склади код, який виводить 1, 2 або 3 відповідно до гілки.`);let area=document.createElement('div');area.className='ce-lines';el.append(area);let result=document.createElement('div');result.className='ce-message';let drag=-1;
   function draw(){area.replaceChildren();order.forEach((id,pos)=>{let row=document.createElement('div');row.className='ce-line';row.draggable=true;row.innerHTML=`<span class="ce-handle">☰ ${pos+1}</span><code>${esc(lines[id]).replace(/ /g,'&nbsp;')}</code>`;row.ondragstart=e=>{drag=pos;e.dataTransfer.setData('text/plain',String(pos))};row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();let from=drag>=0?drag:Number(e.dataTransfer.getData('text/plain'));if(from<0||from>=order.length)return;order.splice(pos,0,order.splice(from,1)[0]);draw()};let ctr=document.createElement('span');ctr.className='ce-controls';['↑','↓'].forEach((symbol,k)=>{let b=document.createElement('button');b.textContent=symbol;b.onclick=()=>{let dest=pos+(k===0?-1:1);if(dest<0||dest>=order.length)return;[order[pos],order[dest]]=[order[dest],order[pos]];draw()};ctr.append(b)});row.append(ctr);area.append(row)})}draw();checkButton(el,()=>{let ok=order.every((n,k)=>n===k);record(i,ok);area.classList.toggle('ce-pass',ok);area.classList.toggle('ce-fail',!ok);message(result,ok,ok?'Правильно! Порядок команд і відступи збережені.':'Помилка. Перевір порядок if, elif, else, команди всередині гілок і print().')});el.append(result);return el});grid(cards); 
 }else if(kind==='doors'){
  const cards=tasks.map((t,i)=>{let el=card(i);info(el,`Для x = ${t.x} визнач, яка гілка виконається.`);let layout=document.createElement('div');layout.className='ce-side-layout';layout.append(code(source(t).replace(/    result = (\d)/g,'    print(f"Гілка $1")').replace('print(f"{result}")','')));let doors=document.createElement('div');doors.className='ce-fairy-doors';let feedback=document.createElement('div');feedback.className='ce-message';['if','elif','else'].forEach((key,j)=>{let b=document.createElement('button');b.className='ce-fairy-door';b.innerHTML=`<span class="ce-arch"><span class="ce-wood">${key}<i class="ce-knob"></i></span></span>`;b.onclick=()=>{let expected=t.x<t.a?'if':t.x<t.b?'elif':'else',ok=key===expected;record(i,ok);if(ok){b.classList.add('opened');message(feedback,true,`Двері ${key} відчинено! x = ${t.x}; перша істинна умова — ${expected}.`)}else{b.classList.add('incorrect');message(feedback,false,`Не ці двері. Перевір: ${t.x} < ${t.a}, потім ${t.x} < ${t.b}.`)}};doors.append(b)});layout.append(doors);el.append(layout,feedback);return el});grid(cards);
 }else if(kind==='lock'){
  const cards=tasks.map((t,i)=>{let el=card(i);info(el,`Визнач точний текст, який з'явиться на екрані.`);let lay=document.createElement('div');lay.className='ce-side-layout';const fmt=(i+variant*3)%10;const widths=[2,3,4,5,6];const width=widths[(i+variant)%widths.length];const suffixes=['*3','!','#','-OK'];const suffix=suffixes[(i+variant)%suffixes.length];const prefixes=['№','Код: ','ID-'];const prefix=prefixes[(i+variant)%prefixes.length];const outputLine=[`print(f"{result}")`,`print(f"{result:0${width}d}")`,`print(f"{result}${suffix}")`,`print(result, '${suffix}', sep='')`,`print(f"{result:0${width}d}${suffix}")`,`print('${prefix}', result, sep='')`,`print(result, result, sep='-')`,`print(f"{result:>5}")`,`print(f"{result:<5}")`,`print(f"{result:+d}")`][fmt];const expectedCode=[String(t.expected),String(t.expected).padStart(width,'0'),`${t.expected}${suffix}`,`${t.expected}${suffix}`,`${String(t.expected).padStart(width,'0')}${suffix}`,`${prefix}${t.expected}`,`${t.expected}-${t.expected}`,String(t.expected).padStart(5,' '),String(t.expected).padEnd(5,' '),(t.expected>=0?'+':'')+t.expected][fmt];lay.append(code(source(t).replace('print(f"{result}")',outputLine)));let safe=document.createElement('div');safe.className='ce-safe';safe.innerHTML=`<div class="ce-safe-door"><span>🔒 СЕЙФ ${i+1}</span><span class="ce-dial">◉</span></div>`;let input=document.createElement('input');input.type='text';input.inputMode='text';input.placeholder='Код';input.setAttribute('aria-label','Код сейфа '+(i+1));let feedback=document.createElement('div');feedback.className='ce-message';let b=checkButton(safe,()=>{if(input.value==='')return;let ok=input.value===expectedCode;record(i,ok);if(ok){safe.classList.add('unlocked');b.disabled=input.disabled=true;message(feedback,true,`Сейф відчинено! Код ${expectedCode}.`)}else if(attempts[i]>=3){b.disabled=input.disabled=true;message(feedback,false,`Три спроби використано. Правильний код: ${expectedCode}.`)}else message(feedback,false,`Код неправильний. Залишилося ${3-attempts[i]} спроб. Підказка: обирається перша істинна умова.`)},'🔑 Відкрити');safe.insertBefore(input,b);lay.append(safe);el.append(lay,feedback);return el});grid(cards);
 }else if(kind==='fix'||kind==='challenge'){
  const cards=tasks.map((t,i)=>{let el=card(i),tests=[t.a-1,t.a,t.b-1,t.b,t.b+2],correct=source(t),bad=source(t,true);let prompt=kind==='fix'?`Програма має повертати 1, якщо x < ${t.a}; 2, якщо ${t.a} ≤ x < ${t.b}; інакше 3. Виправ логічну помилку, не змінюючи задум.`:`Допиши пропущений фрагмент так, щоб програма повертала 1, 2 або 3 для відповідних проміжків.`;let holes=[`if x __ ${t.a}:`,`elif x __ ${t.b}:`,`__ x < ${t.b}:`,`    result = __`];let replacements=[`if x < ${t.a}:`,`elif x < ${t.b}:`,`elif x < ${t.b}:`,`    result = 3`];let target=correct;let template=kind==='fix'?bad:correct.replace(replacements[i%4],holes[i%4]);info(el,prompt);let lay=document.createElement('div');lay.className='ce-triple';let left=document.createElement('div');left.className='ce-explain';left.innerHTML=`<strong>📋 Завдання</strong><p>${esc(prompt)}</p><p>Межі: ${t.a} і ${t.b}</p>`;let editor=document.createElement('textarea');editor.className='ce-editor';editor.spellcheck=false;editor.value=state[i]??template;editor.oninput=()=>state[i]=editor.value;let right=document.createElement('div');right.className='ce-test-panel';right.innerHTML='<strong>🧪 Тестові значення</strong>'+tests.map(x=>`<div>x = ${x}</div>`).join('');lay.append(left,editor,right);let feedback=document.createElement('div');feedback.className='ce-message';checkButton(el,()=>{let text=editor.value,syntaxOK=kind==='challenge'?!text.includes('__'):true;let results=tests.map(x=>{let actual=evaluate(text,x),want=evaluate(target,x);return {x,actual,want,ok:syntaxOK&&!actual.error&&actual.value===want.value}});let ok=results.every(r=>r.ok);record(i,ok);right.innerHTML='<strong>🧪 Результати тестів</strong>'+results.map(r=>`<div class="${r.ok?'ce-pass':'ce-fail'}">x=${r.x}: ${r.ok?'✓':'✗'} отримано ${r.actual.error?esc(r.actual.error):r.actual.value}, очікується ${r.want.value}</div>`).join('');message(feedback,ok,ok?'Усі тести пройдено! Логіка правильна.':kind==='fix'?`Знайди помилку в elif: для середнього проміжку має бути x < ${t.b}, а не x > ${t.b}.`:'Перевір пропуск, оператори порівняння та відступи.');},'▶ Запустити тести');el.append(lay,feedback);return el});grid(cards,'ce-editor-grid');
 }else if(kind==='problems'){
 const data=window.CONDITIONAL_PROBLEMS[variant];
 host.querySelector('h2').innerHTML=`📚 Задачі <span class="ce-heading-variant">· ${esc(data.heading)}</span>`;
 grid(data.items.map((item,i)=>{let el=card(i);el.classList.add('ce-problem-card');el.innerHTML=`<div class="ce-problem-title">${esc(item.name)}</div><p class="ce-problem-text">${esc(item.text)}</p>`;return el;}),'ce-problems-grid');
 }
 host.querySelector('#ce-stats').textContent=kind==='problems'?'6 задач · самостійне програмування':stats();host.querySelector('#ce-reset').onclick=()=>renderConditionalExtras(host,kind,variant);
}

