 {id:"syntax",title:"Синтаксис",image:"syntax.webp",subtitle:"Правила запису коду",intro:"Розберися з відступами, двокрапкою та коментарями у Python."},
 {id:"types",title:"Типи даних",image:"types.webp",subtitle:"int, float, str, bool",intro:"Дізнайся про основні типи значень у Python і функцію type()."},
 {id:"input-output",title:"Введення та виведення",image:"input-output.webp",subtitle:"input() і print()",intro:"Навчися отримувати дані від користувача та показувати результат на екрані."},
 {id:"arithmetic",title:"Арифметика",image:"arithmetic.webp",subtitle:"Оператори та порядок дій",intro:"Ознайомся з арифметичними операторами Python і порядком обчислень."},
 {id:"examples",title:"Приклади",image:"examples-cover.webp",subtitle:"Приклади програм на Python",intro:"Розглянь приклади розв’язування задач із використанням Python."}
