const app=document.getElementById("app"),nav=document.getElementById("nav");
const sectionOrder=["variables", "names", "constants", "syntax", "exercises", "types", "input-output", "arithmetic", "examples", "new-practice"];
const sectionNumber=id=>sectionOrder.indexOf(id)+1;
function drawNav(active){nav.innerHTML=[["home","🏠 Головна"],...lessons.flatMap(l=>l.id==="syntax"?[[l.id,l.title],["exercises","✏️ Вправи"]]:[[l.id,l.id==="conditional-practice"?"🔀 "+l.title:l.id==="for-practice"?"🌟 "+l.title:l.title],...(l.id==="examples"?[["new-practice","🎯 Вправи: введення і виведення"]]:[])])].map(([id,t])=>`<a href="#${id}" class="${id===active?'active':''}">${id==='home'?t:sectionNumber(id)+'. '+t}</a>`).join("")}

function home(){drawNav("home");app.innerHTML=`<section class="hero comic"><img src="assets/home.webp" alt="Python з нуля — навчальний комікс"><div><h1>Python з нуля!</h1><p>Зрозумій код, а не зубри команди!</p><p class="hero-next">Теми. Вправи.<br><strong>А далі — миттєва перевірка!</strong></p><a class="cta" href="#variables">Почати навчання →</a></div></section><section class="tiles" aria-label="Навчальні теми">${lessons.map((l,i)=>`<a href="#${l.id}" class="tile comic"><img src="assets/${l.image}" alt="Комікс до теми ${l.title}"><h2>${sectionNumber(l.id)}. ${l.id==="conditional-practice"?"🔀 ":l.id==="for-practice"?"🌟 ":""}${l.title}</h2><p>Переглянути тему</p></a>${l.id==="examples"?`<a href="#new-practice" class="tile comic"><img src="assets/exercises.webp" alt="Комікс Вправи"><h2>10. Вправи: введення і виведення</h2><p>5 варіантів · 3 інтерактивні вправи</p></a>`:""}${l.id==="syntax"?`<a href="#exercises" class="tile comic"><img src="assets/exercises.webp" alt="Комікс Вправи"><h2>5. Вправи</h2><p>5 варіантів · 3 вправи</p></a>`:""}`).join("")}</section>`}
function lesson(id){const l=lessons.find(x=>x.id===id);if(!l){home();return}drawNav(id);if(id==="while-examples"){app.innerHTML=`<a class="back" href="#while-loop">← До циклу while</a><section class="comic examples-gallery">${Array.from({length:6},(_,i)=>`<img class="lesson-cover" src="assets/while-example-${i+1}.webp" alt="Приклад циклу while — ${i+1}" loading="lazy">`).join("")}</section>`;return}if(id==="while-loop"){app.innerHTML=`<a class="back" href="#for-practice">← До вправ</a><section class="comic examples-gallery"><img class="lesson-cover" src="assets/while-intro.webp" alt="Цикл while: синтаксис, блок-схема та приклад" loading="lazy"></section>`;return}if(id==="for-loop"){app.innerHTML=`<a class="back" href="#conditional-practice">← До вправ</a><section class="comic examples-gallery">${["for-intro-new.webp","update-8.webp","update-4.webp","update-6.webp","update-7.webp","update-5.webp"].map((f,i)=>`<img class="lesson-cover" src="assets/${f}" alt="Цикл for — навчальне зображення ${i+1}" loading="lazy">`).join("")}</section>`;return}if(id==="conditional"){app.innerHTML=`<a class="back" href="#new-practice">← До вправ</a><section class="comic conditional-gallery">${["update-3.webp","conditional-if.webp","conditional-comparison.webp","conditional-logic.webp"].map((f,i)=>`<img src="assets/${f}" alt="${["Загальна структура умовного оператора","Приклад if elif else","Знаки порівняння","Логічні оператори"][i]}" loading="lazy">`).join("")}</section>`;return}if(id==="for-examples"){app.innerHTML=`<a class="back" href="#for-loop">← До циклу for</a><section class="comic examples-gallery">${Array.from({length:41},(_,i)=>`<img class="lesson-cover" src="assets/for-example-${i+1}.webp" alt="Приклад циклу for — ${i+1}" loading="lazy">`).join("")}</section>`;return}if(id==="conditional-examples"){app.innerHTML=`<a class="back" href="#conditional">← До умовного оператора</a><section class="comic examples-landing"><div class="examples-intro-layout"><img src="assets/examples-cover.webp" alt="Комікс Приклади"><div class="examples-intro-copy"><span class="pill">🐍 Практикум Python</span><h1 class="lesson-title">ПРИКЛАДИ!</h1><p class="examples-lead">Від умови — до правильного рішення!</p><p>Розглянь готові програми з умовними операторами if, elif та else.</p></div></div></section><section class="lesson-head comic examples-gallery"><img class="lesson-cover" src="assets/conditional-example-water-state.webp" alt="Приклад Python: water-state" loading="lazy"><img class="lesson-cover" src="assets/conditional-example-compare-two.webp" alt="Приклад Python: compare-two" loading="lazy"><img class="lesson-cover" src="assets/conditional-example-football.webp" alt="Приклад Python: football" loading="lazy"><img class="lesson-cover" src="assets/conditional-example-density.webp" alt="Приклад Python: density" loading="lazy"><img class="lesson-cover" src="assets/conditional-example-grading.webp" alt="Приклад Python: grading" loading="lazy"><img class="lesson-cover" src="assets/conditional-example-last-digit.webp" alt="Приклад Python: last-digit" loading="lazy"><img class="lesson-cover" src="assets/conditional-example-weekday-monday.webp" alt="Приклад Python: weekday-monday" loading="lazy"><img class="lesson-cover" src="assets/conditional-example-weekday-wednesday.webp" alt="Приклад Python: weekday-wednesday" loading="lazy"><img class="lesson-cover" src="assets/conditional-example-baggage.webp" alt="Приклад перевірки ваги багажу" loading="lazy"></section>`;return}if(id==="examples"){app.innerHTML=`<a class="back" href="#home">← До головної</a><section class="comic examples-landing"><div class="examples-intro-layout"><img class="lesson-cover" src="assets/examples-cover.webp" alt="Комікс Приклади"><div class="examples-intro-copy"><span class="pill">🐍 Практикум Python</span><h1 class="lesson-title">ПРИКЛАДИ!</h1><p class="examples-lead">Від рядка коду — до готового результату!</p><p>Розглянь, як Python допомагає розподіляти яблука, обчислювати вартість квитків і знаходити суму цифр числа.</p><p class="examples-highlight">🔎 Читай код, простежуй обчислення та перевіряй результат!</p></div></div></section><section class="lesson-head comic examples-gallery"><img class="lesson-cover" src="assets/example-apples.webp" alt="Приклад розподілу яблук"><img class="lesson-cover" src="assets/example-tickets.webp" alt="Приклад розрахунку вартості квитків"><img class="lesson-cover" src="assets/example-two-digits.webp" alt="Приклад суми цифр двоцифрового числа"><img class="lesson-cover" src="assets/example-three-digits.webp" alt="Приклад суми цифр трицифрового числа"><img class="lesson-cover" src="assets/update-1.webp" alt="Приклад: наступна повна година"><img class="lesson-cover" src="assets/update-2.webp" alt="Приклад: поїздки ліфта"><img class="lesson-cover" src="assets/linear-example-01.webp" alt="Лінійний приклад 01" loading="lazy"><img class="lesson-cover" src="assets/linear-example-02.webp" alt="Лінійний приклад 02" loading="lazy"><img class="lesson-cover" src="assets/linear-example-03.webp" alt="Лінійний приклад 03" loading="lazy"><img class="lesson-cover" src="assets/linear-example-04.webp" alt="Лінійний приклад 04" loading="lazy"><img class="lesson-cover" src="assets/linear-example-05.webp" alt="Лінійний приклад 05" loading="lazy"><img class="lesson-cover" src="assets/linear-example-06.webp" alt="Лінійний приклад 06" loading="lazy"><img class="lesson-cover" src="assets/linear-example-07.webp" alt="Лінійний приклад 07" loading="lazy"><img class="lesson-cover" src="assets/linear-example-08.webp" alt="Приклад: Карусель" loading="lazy"><img class="lesson-cover" src="assets/linear-example-09.webp" alt="Приклад: Паркування" loading="lazy"><img class="lesson-cover" src="assets/linear-example-10.webp" alt="Приклад: Замовлення піци" loading="lazy"><img class="lesson-cover" src="assets/linear-example-11.webp" alt="Приклад: Коробки олівців" loading="lazy"><img class="lesson-cover" src="assets/linear-example-12.webp" alt="Приклад: Квитки в кінотеатрі" loading="lazy"></section><a class="back bottom-back" href="#home">← Повернутися до тем</a>`;return}app.innerHTML=`<a class="back" href="#home">← До головної</a><section class="lesson-head comic ${l.id==='examples'?'examples-page':''}"><img class="lesson-cover" src="assets/${l.image}" alt="Навчальний комікс: ${l.title}">${l.id==="input-output"?`<img class="lesson-cover" src="assets/f-strings.webp" alt="Додатковий комікс: print() та форматування f-рядків">`:""}${l.id==="input-output"?`<img class="lesson-cover" src="assets/output-extra-1.webp" alt="Приклад: параметри sep та end"><img class="lesson-cover" src="assets/output-extra-2.webp" alt="Приклад: використання sep">`:""}${l.id==="examples"?`<img class="lesson-cover" src="assets/example-apples.webp" alt="Приклад розподілу яблук"><img class="lesson-cover" src="assets/example-tickets.webp" alt="Приклад розрахунку вартості квитків"><img class="lesson-cover" src="assets/example-two-digits.webp" alt="Приклад суми цифр двоцифрового числа"><img class="lesson-cover" src="assets/example-three-digits.webp" alt="Приклад суми цифр трицифрового числа">`:""}<div class="lesson-copy"><span class="pill">🐍 Тема ${sectionNumber(l.id)}</span><h1 class="lesson-title">${l.title}</h1><p class="subtitle">${l.subtitle}</p><p>${l.intro}</p></div></section><a class="back bottom-back" href="#home">← Повернутися до тем</a>`}
function route(){const requested=decodeURIComponent(location.hash.slice(1))||"home";const id=sectionOrder.includes(requested)?requested:"home";id==="home"?home():id==="for-practice"?(drawNav("for-practice"),app.innerHTML=`<div id="for-practice-root"></div>`,renderForPractice()):id==="conditional-practice"?(drawNav("conditional-practice"),app.innerHTML=`<div id="conditional-practice-root"></div>`,renderConditionalPractice()):id==="new-practice"?(drawNav("new-practice"),app.innerHTML=`<div id="new-practice-root"></div>`,renderNewPractice()):id==="exercises"?(drawNav("exercises"),app.innerHTML=`<div id="exercise-root"></div>`,renderExercises()):lesson(id);window.scrollTo(0,0)}
window.addEventListener("hashchange",route);route();


(()=>{const map={"variables.webp": "mini-lessons/variables.html", "names.webp": "mini-lessons/names.html", "constants.webp": "mini-lessons/constants.html", "syntax.webp": "mini-lessons/syntax.html", "types.webp": "mini-lessons/types.html", "input-output.webp": "mini-lessons/input-output.html", "f-strings.webp": "mini-lessons/f-strings.html", "output-extra-1.webp": "mini-lessons/output-extra-1.html", "output-extra-2.webp": "mini-lessons/output-extra-2.html", "arithmetic.webp": "mini-lessons/arithmetic.html", "example-apples.webp": "mini-lessons/10_pryklad_yabluka.html", "example-tickets.webp": "mini-lessons/11_pryklad_kvytky.html", "example-two-digits.webp": "mini-lessons/12_pryklad_dvotsyfrove.html", "example-three-digits.webp": "mini-lessons/13_pryklad_trytsyfrove.html", "update-1.webp": "mini-lessons/14_pryklad_godyna.html", "update-2.webp": "mini-lessons/15_pryklad_lift.html", "linear-example-01.webp": "mini-lessons/16_pryklad_terezy.html", "linear-example-02.webp": "mini-lessons/17_pryklad_sashko.html", "linear-example-03.webp": "mini-lessons/18_pryklad_petrus.html", "linear-example-04.webp": "mini-lessons/19_pryklad_ryaba.html", "linear-example-05.webp": "mini-lessons/20_pryklad_terarium.html", "linear-example-06.webp": "mini-lessons/21_pryklad_dzerkalo.html", "linear-example-07.webp": "mini-lessons/22_pryklad_kapeliushok.html", "linear-example-08.webp": "mini-lessons/36_pryklad_karusel.html", "linear-example-09.webp": "mini-lessons/37_pryklad_parkuvannia.html", "linear-example-10.webp": "mini-lessons/38_pryklad_pitsa.html", "linear-example-11.webp": "mini-lessons/39_pryklad_olivtsi.html", "linear-example-12.webp": "mini-lessons/40_pryklad_kino.html"};let dialog=null,trigger=null,oldOverflow='';
function close(){if(!dialog)return;const d=dialog;dialog=null;const f=d.querySelector('iframe');if(f)f.remove();d.close();d.remove();document.body.style.overflow=oldOverflow;if(trigger&&trigger.isConnected)trigger.focus({preventScroll:true});trigger=null;}
function open(path,button){close();trigger=button;oldOverflow=document.body.style.overflow;dialog=document.createElement('dialog');dialog.className='alive-dialog';dialog.setAttribute('aria-label','Оживи комікс');dialog.innerHTML='<div class="alive-toolbar"><span>▶ Оживи комікс</span><button type="button" class="alive-close" aria-label="Закрити мініурок">✕</button></div>';const f=document.createElement('iframe');f.className='alive-frame';f.title='Анімований мініурок Python';f.allow='autoplay';f.src=path;dialog.append(f);document.body.append(dialog);dialog.querySelector('.alive-close').addEventListener('click',close);dialog.addEventListener('cancel',e=>{e.preventDefault();close()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});dialog.showModal();document.body.style.overflow='hidden';dialog.querySelector('.alive-close').focus();
const d=dialog,bar=d.querySelector('.alive-toolbar');let drag=null;
function place(x,y){const r=d.getBoundingClientRect();d.style.margin='0';d.style.inset='auto';d.style.left=Math.max(0,Math.min(x,innerWidth-r.width))+'px';d.style.top=Math.max(0,Math.min(y,innerHeight-r.height))+'px';}
bar.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.button!==0)return;const r=d.getBoundingClientRect();drag={id:e.pointerId,x:e.clientX-r.left,y:e.clientY-r.top};bar.setPointerCapture(e.pointerId);e.preventDefault()});
bar.addEventListener('pointermove',e=>{if(drag&&drag.id===e.pointerId)place(e.clientX-drag.x,e.clientY-drag.y)});
for(const event of ['pointerup','pointercancel','lostpointercapture'])bar.addEventListener(event,()=>{drag=null});
function fit(){if(!d.isConnected)return;const r=d.getBoundingClientRect();if(d.style.left)place(r.left,r.top);}
window.addEventListener('resize',fit);d.addEventListener('close',()=>window.removeEventListener('resize',fit),{once:true});
f.addEventListener('load',()=>{try{const doc=f.contentDocument;const main=doc.querySelector('main');if(!main)return;const style=doc.createElement('style');style.textContent=`html,body{margin:0!important;width:100%!important;height:100%!important;overflow:hidden!important}body{display:block!important;padding:0!important;min-height:0!important}main{position:absolute!important;left:50%;top:50%;margin:0!important;width:min(1100px, max(620px, 92vw))!important;max-width:none!important;transform-origin:center center;box-sizing:border-box}pre{white-space:pre-wrap!important;overflow-wrap:anywhere!important;overflow:visible!important;max-width:100%!important} .editor{overflow:visible!important} `;doc.head.append(style);let pending=false;function resizeLesson(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;if(!f.isConnected)return;const w=main.offsetWidth,hh=Math.max(main.offsetHeight,main.scrollHeight);if(w&&hh)main.style.transform='translate(-50%,-50%) scale('+Math.min((f.clientWidth-12)/w,(f.clientHeight-12)/hh,1.8)+')';});}const ro=new ResizeObserver(resizeLesson);ro.observe(main);ro.observe(f);const mo=new MutationObserver(resizeLesson);mo.observe(main,{childList:true,subtree:true,characterData:true});d.addEventListener('close',()=>{ro.disconnect();mo.disconnect()},{once:true});resizeLesson();}catch(e){} });}
function attach(){if(!['variables','names','constants','syntax','types','input-output','arithmetic','examples','conditional','conditional-examples'].includes(location.hash.slice(1)))return;document.querySelectorAll('#app img.lesson-cover, #app .conditional-gallery img').forEach(img=>{const key=img.getAttribute('src').split('/').pop();if(!map[key]||img.nextElementSibling?.classList.contains('alive-controls'))return;const wrap=document.createElement('div');wrap.className='alive-controls';wrap.innerHTML='<button type="button" class="alive-launch"><span class="alive-play" aria-hidden="true">▶</span> Оживи комікс<span class="alive-snake" aria-hidden="true">🐍</span></button><span class="alive-caption">Переглянь, як працює код!</span>';const b=wrap.querySelector('button');b.addEventListener('click',()=>open(map[key],b));img.after(wrap);});}
window.addEventListener('hashchange',()=>{close();attach()});attach();})();
